    // [WSCoop] Same as GiveAbilitySet / GiveGameplayEffect, but hands back what was granted so a luminary
    // respec can take it away again (see WSLuminaryRespec).
    bool WSGiveAbilitySet(UHercAbilityComponent AbilityComponent, FHercAbilitySet_GrantedHandles& OutHandles) const
    {
        if (Type != EProgressionUnlockType::Skill || AbilitySet == nullptr)
            return false;
        OutHandles = AbilityComponent.GiveAbilitySet(AbilitySet);
        return true;
    }

    void WSGiveGameplayEffect(UHercAbilityComponent AbilityComponent, TArray<FActiveGameplayEffectHandle>& OutHandles) const
    {
        if (Type != EProgressionUnlockType::GameplayEffect || !GameplayEffect.IsValid())
            return;
        TSubclassOf<UGameplayEffect> LoadedGameplayEffect = GameplayEffect.TryLoadClass();
        if (LoadedGameplayEffect == nullptr)
            return;
        FGameplayEffectSpecHandle NewEffectSpec = AbilityComponent.MakeOutgoingSpec(LoadedGameplayEffect, 0, AbilityComponent.MakeEffectContext());
        NewEffectSpec.Spec.SetByCallerMagnitude(GameplayTags::Effects_Set_Magnitude, Magnitude);
        for (int Idx = 0; Idx < Stacks; Idx++)
        {
            OutHandles.Add(AbilityComponent.ApplyGameplayEffectSpecToSelf(NewEffectSpec));
        }
    }
